# 데이터 병렬로 통신을 계산 뒤에 숨기려면 GPU 한 장이 한 스텝에 토큰을 몇 개 처리해야 하나
F = 400e12                                   # 실효 bf16 FLOP/s (H100 기준 어림)
def min_tokens(comm_params, W, bytes_per=2):
    # 계산 6·Ψ·T / F  ≥  통신 comm_params·Ψ·bytes / W   →   T ≥ comm_params·bytes·F / (6·W)
    return comm_params * bytes_per * F / (6 * W)
for name, W in [("NVLink 450GB/s", 450e9), ("IB 400Gb/s=50GB/s", 50e9), ("이더넷 100Gb/s", 12.5e9)]:
    print(f"{name:20s} DDP/ZeRO-1,2: {min_tokens(2, W):7.0f} 토큰  FSDP: {min_tokens(3, W):7.0f} 토큰")

# 인터리브 파이프라인: stage 마다 층 묶음을 v 개 맡으면 거품이 1/v 로, 대신 점대점 통신은 v 배
p, m = 16, 16
for v in (1, 2, 4, 8):
    print(f"v={v}: 거품/유효계산 = {(p - 1) / (v * m):.3f}, stage 경계 통신 {v}배")

